/** Exercises forced LMDB strategies through transaction HTTP requests and the real server controller. */
class LmdbTransactionalForcedExecutionStrategyIT {

	private static final String REPOSITORY_ID = "forced-lmdb-transaction";
	private static final String NESTED_LOOP = "nestedLoop";
	private static final String BOGUS_STRATEGY = "totally-bogus-strategy-name";
	private static final String ASK_QUERY = "ASK { <http://example.com/alice> "
			+ "<http://example.com/worksAt> <http://example.com/acme> }";
	private static final String JOIN_QUERY = "PREFIX ex: <http://example.com/> "
			+ "SELECT ?person WHERE { ?person ex:knows ?other . "
			+ "?person ex:worksAt ?company . ?other ex:worksAt ?company }";

	private static TestServer server;
	private static HTTPRepository lmdbRepository;

	@BeforeAll
	static void startServer() throws Exception {
		server = new TestServer();
		server.includeTestClassesInWebapp();
		try {
			server.start();
			RemoteRepositoryManager manager = RemoteRepositoryManager.getInstance(TestServer.SERVER_URL);
			LmdbStoreConfig lmdbConfig = new LmdbStoreConfig("spoc,posc,ospc")
					.setNativeEvaluationEnabled(true)
					.setDirectAdjacencyEnabled(true);
			manager.addRepositoryConfig(new RepositoryConfig(REPOSITORY_ID, new SailRepositoryConfig(lmdbConfig)));
			lmdbRepository = new HTTPRepository(Protocol.getRepositoryLocation(TestServer.SERVER_URL, REPOSITORY_ID));
			try (RepositoryConnection connection = lmdbRepository.getConnection()) {
				connection.add(Values.iri("http://example.com/alice"), Values.iri("http://example.com/knows"),
						Values.iri("http://example.com/bob"));
				connection.add(Values.iri("http://example.com/alice"), Values.iri("http://example.com/worksAt"),
						Values.iri("http://example.com/acme"));
				connection.add(Values.iri("http://example.com/bob"), Values.iri("http://example.com/worksAt"),
						Values.iri("http://example.com/acme"));
			}
		} catch (Exception e) {
			server.stop();
			throw e;
		}
	}

	@AfterAll
	static void stopServer() throws Exception {
		if (lmdbRepository != null) {
			lmdbRepository.shutDown();
		}
		if (server != null) {
			server.stop();
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void queryExecutesWithForcedNestedLoopStrategy() {
		for (boolean transaction : new boolean[] { false, true }) {
			withConnection(lmdbRepository, transaction, connection -> {
				TupleQuery query = prepareJoinQuery(connection, NESTED_LOOP);
				try (TupleQueryResult result = query.evaluate()) {
					assertThat(QueryResults.asList(result)).hasSize(1);
				}
			});
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void explainReportsForcedNestedLoopStrategy() {
		for (boolean transaction : new boolean[] { false, true }) {
			withConnection(lmdbRepository, transaction, connection -> {
				TupleQuery query = prepareJoinQuery(connection, NESTED_LOOP);
				Explanation explanation = query.explain(Explanation.Level.Executed);
				assertThat(explanation.toString()).contains("nativeExecutionPath=" + NESTED_LOOP);
			});
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void queryRejectsUnknownForcedStrategy() {
		for (boolean transaction : new boolean[] { false, true }) {
			withConnection(lmdbRepository, transaction, connection -> {
				TupleQuery query = prepareJoinQuery(connection, BOGUS_STRATEGY);
				assertThatThrownBy(() -> {
					try (TupleQueryResult result = query.evaluate()) {
						QueryResults.asList(result);
					}
				}).isInstanceOf(QueryEvaluationException.class);
			});
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void explainRejectsUnknownForcedStrategy() {
		for (boolean transaction : new boolean[] { false, true }) {
			withConnection(lmdbRepository, transaction, connection -> {
				TupleQuery query = prepareJoinQuery(connection, BOGUS_STRATEGY);
				assertThatThrownBy(() -> query.explain(Explanation.Level.Optimized))
						.isInstanceOf(QueryEvaluationException.class);
			});
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void unsetStrategyLeavesQueryAdaptive() {
		for (boolean transaction : new boolean[] { false, true }) {
			withConnection(lmdbRepository, transaction, connection -> {
				BooleanQuery query = connection.prepareBooleanQuery(ASK_QUERY);
				assertThat(query.evaluate()).isTrue();
				BooleanQuery sentinelQuery = connection.prepareBooleanQuery(ASK_QUERY);
				((AbstractHTTPQuery) sentinelQuery)
						.setForcedLmdbExecutionStrategy(Protocol.LMDB_FORCED_EXECUTION_STRATEGY_NOT_ACTIVATED);
				assertThat(sentinelQuery.evaluate()).isTrue();
				BooleanQuery blankQuery = connection.prepareBooleanQuery(ASK_QUERY);
				((AbstractHTTPQuery) blankQuery).setForcedLmdbExecutionStrategy(" \t");
				assertThat(blankQuery.evaluate()).isTrue();
			});
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void nonLmdbRepositoryIgnoresUnknownForcedStrategy() {
		HTTPRepository memoryRepository = new HTTPRepository(
				Protocol.getRepositoryLocation(TestServer.SERVER_URL, TestServer.TEST_REPO_ID));
		try {
			for (boolean transaction : new boolean[] { false, true }) {
				withConnection(memoryRepository, transaction, connection -> {
					BooleanQuery query = connection.prepareBooleanQuery("ASK { }");
					((AbstractHTTPQuery) query).setForcedLmdbExecutionStrategy(BOGUS_STRATEGY);
					assertThat(query.evaluate()).isTrue();
				});
			}
		} finally {
			memoryRepository.shutDown();
		}
	}

	private static void withConnection(HTTPRepository repository, boolean transaction,
			Consumer<RepositoryConnection> action) {
		try (RepositoryConnection connection = repository.getConnection()) {
			if (transaction) {
				connection.begin();
			}
			action.accept(connection);
			if (transaction) {
				connection.commit();
			}
		}
	}

	private static TupleQuery prepareJoinQuery(RepositoryConnection connection, String strategy) {
		TupleQuery query = connection.prepareTupleQuery(JOIN_QUERY);
		((AbstractHTTPQuery) query).setForcedLmdbExecutionStrategy(strategy);
		return query;
	}
}
